mapper.select:
select gqb.questionBank_id as questionBankId, gqb.questionBank_description as questionBankDescription, gqb.questionBank_type as questionBankType, gqb.questionFirstCategory_name as questionFirstCategoryName, gqb.questionSecondCategory_name as questionSecondCategoryName, gqb.questionBank_difficulty as questionBankDifficulty, gqb.questionBank_state as questionBankState, ifnull(gfqbu.firstCategoryQuestionBankUser_answerStatus, 0) as questionBankAnswerStatus, gqb.questionBank_createTime as questionBankCreateTime, gqb.questionBank_updateTime as questionBankUpdateTime from general_questionBank gqb left join general_firstCategory_questionBank_user gfqbu on gqb.questionBank_id = gfqbu.firstCategoryQuestionBankUser_questionBankId and gfqbu.firstCategoryQuestionBankUser_userId = #{userId}
gqb.deleted = 0 and gqb.questionBank_state = 1
and gqb.questionFirstCategory_id = #{query.questionFirstCategoryId}
and gqb.questionSecondCategory_id = #{query.questionSecondCategoryId}
and gqb.questionBank_type = #{query.questionBankType}
and gqb.questionBank_difficulty = #{query.questionBankDifficulty}
and gqb.questionBank_description like concat('%', #{query.questionBankDescription}, '%')
and ifnull(gfqbu.firstCategoryQuestionBankUser_answerStatus, 0) = #{query.questionBankAnswerStatus}
order by gqb.questionBank_createTime desc
